```
if start or end is blocked: return -1
enqueue (0,0), mark visited, dist = 1
while queue not empty:
    for each cell in current level:
        if cell is (n-1, n-1): return dist
        for each of 8 neighbors:
            if in bounds and unvisited and == 0:
                mark visited, enqueue
    dist = dist + 1
return -1
```

code.cpp:
class Solution {
public:
    int shortestPathBinaryMatrix(vector<vector<int>>& grid) {
        int n = grid.size();
        if (grid[0][0] == 1 || grid[n - 1][n - 1] == 1) return -1;
        if (n == 1) return 1;

        int dx[8] = {-1, -1, -1, 0, 0, 1, 1, 1};
        int dy[8] = {-1, 0, 1, -1, 1, -1, 0, 1};

        queue<pair<int, int>> q;
        q.push({0, 0});
        grid[0][0] = 1;
        int dist = 1;

        while (!q.empty()) {
            int sz = q.size();
            dist++;
            for (int i = 0; i < sz; i++) {
                auto [x, y] = q.front();
                q.pop();
                for (int d = 0; d < 8; d++) {
                    int nx = x + dx[d];
                    int ny = y + dy[d];
                    if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
                    if (grid[nx][ny] == 1) continue;
                    if (nx == n - 1 && ny == n - 1) return dist;
                    grid[nx][ny] = 1;
                    q.push({nx, ny});
                }
            }
        }
        return -1;
    }
};
